// Fork of DoubleRedGaming Neon Sound Visualization:
// https://www.shadertoy.com/view/3tyXDt
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;

    vec3 col = vec3(0.0);

    float v = texture(iChannel0, vec2(uv.x, 1.0)).x;

	col += pow(1.0 - abs(uv.y - 0.5), clamp(4.0 / v, 0.0, 25.0));
    col *= mix(vec3(1.0, 2.0, 0.5), vec3(0.5,2.0,1.0), v);
    // col *= col;

    // Output to screen
    fragColor = vec4(col,1.0);
}
